```typescript
function processData(data: any, seen = new WeakSet()): any {
  if (typeof data === 'object' && data !== null) {
    // Detect circular reference
    if (seen.has(data)) {
      return '[Circular]';
    }
    seen.add(data);

    const result: any = Array.isArray(data) ? [] : {};
    for (const key in data) {
      result[key] = processData(data[key], seen);
    }
    return result;
  }
  return data;
}
