2. Race condition with concurrent requests
3. Token space too small

**Root Cause Category**: unique_key_collision

## Fix
```typescript
import { randomBytes } from 'crypto';

// Better token generation
function generateToken(): string {
  return randomBytes(32).toString('hex'); // 256-bit token
}

// Retry on collision
async function createSession(userId: string, retries = 3): Promise<Session> {
  for (let i = 0; i < retries; i++) {
    try {
      const session = new Session({
        userId,
        token: generateToken(),
        expiresAt: new Date(Date.now() + 3600000)
      });

      await session.save();
      return session;
    } catch (error) {
      if (error.code === 11000 && i < retries - 1) {
        // Duplicate key, retry with new token
        continue;
      }
      throw error;
    }
  }

  throw new Error('Failed to create unique session token');
}
```

## Verification
